    IF encode(sha256(convert_to(pg_get_functiondef(to_regprocedure(f.signature)),'UTF8')),'hex') IS DISTINCT FROM f.digest
      OR (SELECT p.proowner<>'postgres'::regrole OR NOT p.prosecdef
